export type GobblerSize = 'SMALL' | 'MEDIUM' | 'LARGE';
export type PlayerSide = 'X' | 'O';
export interface GobblerPiece {
    id: string;
    side: PlayerSide;
    size: GobblerSize;
}
export type GobblerCell = GobblerPiece[];
export interface GobblerState {
    board: GobblerCell[];
    playerXId?: string;
    playerOId?: string;
    currentTurn: PlayerSide;
    inventory: {
        X: GobblerPiece[];
        O: GobblerPiece[];
    };
    scores: {
        X: number;
        O: number;
    };
    winner?: PlayerSide | 'DRAW';
    winningLine?: number[];
}
